/// Whether `stat` is one of [`STATS`].
#[must_use]
pub fn contains(stat: &str) -> bool {
    STATS.binary_search(&stat).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_stats_should_be_sorted_and_apart_from_the_mapped_rows() {
        use crate::poe1::mapping::{HIT_ROWS, NO_EFFECT, ROWS};
        assert!(STATS.windows(2).all(|w| w[0] < w[1]));
        for s in STATS {
            assert!(HIT_ROWS.iter().all(|r| r.0 != s), "{s}");
            assert!(ROWS.iter().all(|r| r.0 != s), "{s}");
            assert!(NO_EFFECT.iter().all(|r| r.0 != s), "{s}");
        }
    }
}
